package com.cgengine.VertexDelete;
import com.cgengine.math.*; import com.cgengine.model.*; import com.cgengine.render_engine.*; import org.junit.jupiter.api.Test; import java.util.*; import static org.junit.jupiter.api.Assertions.*;
class EraserTest { private static Model model(){Model m=new Model();m.vertices.addAll(List.of(new Vector3f(0,0,0),new Vector3f(1,0,0),new Vector3f(0,1,0),new Vector3f(1,1,0)));m.textureVertices.addAll(List.of(new Vector2f(0,0),new Vector2f(1,0),new Vector2f(0,1),new Vector2f(1,1)));for(int[] i:List.of(new int[]{0,1,2},new int[]{1,3,2})){Polygon p=new Polygon();p.setVertexIndices(new ArrayList<>(List.of(i[0],i[1],i[2])));p.setTextureVertexIndices(new ArrayList<>(List.of(i[0],i[1],i[2])));p.setBaseColor(ColorRgb.BLUE);m.polygons.add(p);}m.computeNormals();m.setTexture(new Texture2D(1,1,new int[]{0xFFFFFFFF}));return m;} @Test void removesAffectedFacesAndPreservesAttributes(){Model s=model(),r=Eraser.vertexDelete(s,List.of(0),false,false,false,false);ModelValidator.validate(r);assertEquals(3,r.vertices.size());assertEquals(1,r.polygons.size());assertEquals(ColorRgb.BLUE,r.polygons.getFirst().getBaseColor());assertSame(s.getTexture(),r.getTexture());assertEquals(2,s.polygons.size());} @Test void supportsNoUvNoNormalsAndDeletion(){Model s=model();for(Polygon p:s.polygons){p.setTextureVertexIndices(new ArrayList<>());p.setNormalIndices(new ArrayList<>());}s.textureVertices.clear();s.normals.clear();Model r=Eraser.vertexDelete(s,List.of(0),true,true,true,false);ModelValidator.validate(r);assertTrue(r.textureVertices.isEmpty());assertTrue(r.normals.isEmpty());} @Test void rejectsDuplicateAndOutOfRange(){Model s=model();assertThrows(IllegalArgumentException.class,()->Eraser.vertexDelete(s,List.of(1,1),false,false,false,false));assertThrows(IllegalArgumentException.class,()->Eraser.vertexDelete(s,List.of(9),false,false,false,false));assertDoesNotThrow(()->Eraser.vertexDelete(s,List.of(),false,false,false,false));} @Test void removePolygonsProducesValidEmptyModel(){Model r=Eraser.vertexDelete(model(),List.of(0),false,false,false,true);assertTrue(r.polygons.isEmpty());ModelValidator.validate(r);} }
